package org.openidentity.protocol.v2;
import org.junit.jupiter.api.Test;import java.util.HexFormat;import static org.junit.jupiter.api.Assertions.*;
final class ProtocolV2RecoveryDeactivationTest {
 static final HexFormat H=HexFormat.of();
 static final String V314_PREV="",V314_SIGNED="",V314_STATE="",V314_HASH="12207dea32b429321dfdd4c725ab97187b027015cc3c2bea2d66e3a373294af8110f";
 static final String V315_PREV="",V315_SIGNED="",V315_STATE="",V315_HASH="1220ab8a273ea83b9c9adc1773eb906d4fe19ab10febdab269f98807ebbf6a506c4c";
 static final String V316_PREV="",V316_SIGNED="",V316_STATE="",V316_HASH="1220a13c127e29975c962e7f349b3cd135e31048c0373e04b5ab27090d6b3a7df71c";
 static final String V317_PREV="",V317_SIGNED="",V317_STATE="",V317_HASH="12207b9f0e66bf6e14c6ab7b11ad802c8cca81c77b2f0aaeddf006b37ab011e2910c";
 static final String V318_PREV="",V318_SIGNED="",V318_STATE="",V318_HASH="1220884ee0fd52ce2081109a96f920d41e0ca652a76cd5dd01c04ae6a934f0e89d8f";
 static final String V324_PREV="",V324_SIGNED="",V324_STATE="",V324_HASH="1220e7a3ec31a906e1fa904090dce4ea4ed3a3749f2c3b1d6fd9be3f8681d18e1629";
 @Test void v314(){check(V314_PREV,V314_SIGNED,V314_STATE,V314_HASH);}
 @Test void v315(){check(V315_PREV,V315_SIGNED,V315_STATE,V315_HASH);}
 @Test void v316(){check(V316_PREV,V316_SIGNED,V316_STATE,V316_HASH);}
 @Test void v317(){check(V317_PREV,V317_SIGNED,V317_STATE,V317_HASH);}
 @Test void v318(){check(V318_PREV,V318_SIGNED,V318_STATE,V318_HASH);}
 @Test void v324(){check(V324_PREV,V324_SIGNED,V324_STATE,V324_HASH);}
 @Test void recoverRejectsOrdinaryControllerAuthorization(){assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(""),H.parseHex("")));}
 @Test void tamperedRecoverySignatureRejected(){byte[] x=H.parseHex(V314_SIGNED);x[x.length-1]^=1;assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(V314_PREV),x));}
 @Test void deactivatedOrdinaryOperationRejected(){assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(V317_STATE),H.parseHex(V324_SIGNED)));}
 private static void check(String p,String s,String state,String hash){var t=ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(p),H.parseHex(s));assertEquals(state,H.formatHex(t.successorStateBytes()));assertEquals(hash,H.formatHex(t.successorStateHash()));}
}
